Record Sale
  Define code, quantity As Integer;
EndRecord

Function price <- PriceOf(code As Integer)
  Define price As Integer;
  Switch code Do
    1:
      price <- 3;
    2:
      price <- 5;
    3:
      price <- 2;
    4:
      price <- 1;
    Otherwise:
      price <- 2;
  EndSwitch
EndFunction

Function name <- NameOf(code As Integer)
  Define name As String;
  Switch code Do
    1:
      name <- "Juice";
    2:
      name <- "Sandwich";
    3:
      name <- "Biscuit";
    4:
      name <- "Water";
    Otherwise:
      name <- "Fruit";
  EndSwitch
EndFunction

Function amount <- Amount(sale As Sale)
  Define amount As Integer;
  amount <- PriceOf(sale.code) * sale.quantity;
EndFunction

Function big <- OverFive(figure As Integer)
  Define big As Boolean;
  big <- figure > 5;
EndFunction

Function total <- Sum(a As Integer, b As Integer)
  Define total As Integer;
  total <- a + b;
EndFunction

Function discounted <- WithDiscount(total As Integer)
  Define discounted As Integer;
  discounted <- total - total Div 10;
EndFunction

Function mapped <- Map(sales As Vector<Sale>, f As Function(Sale) As Integer)
  Define mapped As Vector<Integer> <- vector();
  For Each sale In sales Do
    mapped.append(f(sale));
  EndFor
EndFunction

Function chosen <- Filter(amounts As Vector<Integer>, condition As Function(Integer) As Boolean)
  Define chosen As Vector<Integer> <- vector();
  For Each entry In amounts Do
    If condition(entry) Then
      chosen.append(entry);
    EndIf
  EndFor
EndFunction

Function accumulated <- Reduce(amounts As Vector<Integer>, f As Function(Integer, Integer) As Integer, initial As Integer)
  Define accumulated As Integer <- initial;
  For Each entry In amounts Do
    accumulated <- f(accumulated, entry);
  EndFor
EndFunction

Function counter <- UnitsOf(code As Integer)
  Define counter As Function(Sale) As Integer <- Function(sale As Sale) As Integer
    If sale.code = code Then
      Return sale.quantity;
    EndIf
    Return 0;
  EndFunction;
EndFunction

Function star <- Star(sales As Vector<Sale>)
  Define star As String <- "None";
  Define best As Integer <- 0;
  For code <- 1 To 5 Do
    Define units As Integer <- Reduce(Map(sales, UnitsOf(code)), Sum, 0);
    If units > best Then
      best <- units;
      star <- NameOf(code);
    EndIf
  EndFor
EndFunction

Algorithm Report
  Define sales As Vector<Sale> <- vector();
  Define code, quantity As Integer;
  Read code;
  While code <> 0 Do
    Read quantity;
    sales.append(Sale(code, quantity));
    Read code;
  EndWhile
  Define amounts As Vector<Integer> <- Map(sales, Amount);
  Define total As Integer <- Reduce(amounts, Sum, 0);
  Write "Total: ", total;
  Write "With discount: ", WithDiscount(total);
  Write "Sales over 5 pesos: ", Filter(amounts, OverFive).length();
  Write "Star product: ", Star(sales);
EndAlgorithm
